query ACRRepositoryScopes($orgId: String!) {
  catalog(orgId: $orgId, dimension: REPO) {
    values {
      value
      count
      __typename
    }
    __typename
  }
}

query CatalogValues($orgId: String!, $dimension: DimensionInput!) {
  catalog(orgId: $orgId, dimension: $dimension) {
    values {
      value
      count
      __typename
    }
    __typename
  }
}

query CognitiveLoad($input: CognitiveLoadInput!) {
  cognitiveLoad(input: $input) {
    orgId
    teamId
    totalDays
    signals {
      day
      prInterruptionLoad
      contextSpreadCount
      reviewRequestLoad
      afterHoursCommitRatio
      weekendCommitRatio
      __typename
    }
    __typename
  }
}

query ComplexityTimeseries($input: ComplexityTimeseriesInput!) {
  complexityTimeseries(input: $input) {
    points {
      date
      scopeId
      scopeName
      locTotal
      cyclomaticPerKloc
      cyclomaticTotal
      cyclomaticAvg
      highComplexityFunctions
      veryHighComplexityFunctions
      __typename
    }
    totalScope
    __typename
  }
}

query Hotspots($input: HotspotsInput!) {
  hotspots(input: $input) {
    rows {
      filePath
      repoId
      repoName
      churnLoc30d
      churnCommits30d
      cyclomaticTotal
      cyclomaticAvg
      blameConcentration
      riskScore
      evidenceUrl
      __typename
    }
    __typename
  }
}

query InvestmentBreakdown($orgId: String!, $batch: AnalyticsRequestInput!) {
  analytics(orgId: $orgId, batch: $batch) {
    breakdowns {
      dimension
      measure
      items {
        key
        value
        __typename
      }
      __typename
    }
    evidenceQualityDistribution
    evidenceQualityStats {
      mean
      stddev
      total
      bandCounts
      __typename
    }
    __typename
  }
}

query InvestmentFull($orgId: String!, $batch: AnalyticsRequestInput!) {
  analytics(orgId: $orgId, batch: $batch) {
    breakdowns {
      dimension
      measure
      items {
        key
        value
        __typename
      }
      __typename
    }
    sankey {
      nodes {
        id
        label
        dimension
        value
        __typename
      }
      edges {
        source
        target
        value
        __typename
      }
      coverage {
        teamCoverage
        repoCoverage
        __typename
      }
      unit
      __typename
    }
    __typename
  }
}

query SecurityOverview($orgId: String!, $filters: SecurityAlertFilterInput) {
  securityOverview(orgId: $orgId, filters: $filters) {
    kpis {
      openTotal
      critical
      high
      meanDaysToFix30d
      openDelta30d
      __typename
    }
    severityBreakdown {
      severity
      count
      __typename
    }
    topRepos {
      repoId
      repoName
      repoUrl
      count
      __typename
    }
    trend {
      day
      opened
      fixed
      __typename
    }
    __typename
  }
}

query WorkGraphArtifacts($orgId: String!, $filters: WorkGraphEdgeFilterInput) {
  workGraphArtifacts(orgId: $orgId, filters: $filters) {
    rows {
      nodeType
      nodeId
      displayName
      degree
      evidence
      __typename
    }
    degradedReason
    __typename
  }
}

query WorkGraphFlow($orgId: String!, $filters: WorkGraphEdgeFilterInput) {
  workGraphFlow(orgId: $orgId, filters: $filters) {
    rows {
      nodeType
      inflow
      outflow
      __typename
    }
    degradedReason
    __typename
  }
}
